  '金沙': 'Sables d\'Or',  // PLAYERS[4]、FACTIONS.4.name

  // ── 阵营说明 ──
  '钢铁与工厂的工业强国，信奉火力与装甲。': 'Puissance industrielle de l\'acier et des usines, adepte de la puissance de feu et du blindage.',  // FACTIONS.1.culture
  '履带车辆防御 +5%；陆上单位在兵工厂的修理费 −20%。': 'Véhicules chenillés : défense +5 % ; unités terrestres : frais de réparation −20 % à l\'usine.',  // FACTIONS.1.trait
  '海洋与天空的联邦，重视技术与后勤。': 'Fédération de la mer et du ciel, attachée à la technique et à la logistique.',  // FACTIONS.2.culture
  '航空单位和舰船视野 +1；航空单位在机场、舰船在港口的修理费 −20%。': 'Unités aériennes et navires : vision +1 ; frais de réparation −20 % pour les unités aériennes à l\'aéroport et les navires au port.',  // FACTIONS.2.trait
  '山林与雪原的游击之民，擅长地形与隐蔽。': 'Peuple de guérilla des forêts de montagne et de la toundra, maître du terrain et du camouflage.',  // FACTIONS.3.culture
  '步兵类单位造价 −5%；位于森林、山地的步兵类单位防御 +10%；中型坦克、重型坦克、火箭炮造价 +5%。': 'Unités d\'infanterie : coût −5 % ; unités d\'infanterie en forêt et en montagne : défense +10 % ; chars moyens, chars lourds et lance-roquettes : coût +5 %.',  // FACTIONS.3.trait
  '商路与黄金的城邦联盟，凭借财力与城墙作战。': 'Ligue de cités des routes marchandes et de l\'or, qui combat grâce à sa richesse et à ses remparts.',  // FACTIONS.4.culture
  '城市收入 +10%；位于建筑的单位防御 +5%，位于平原的单位防御 −5%。': 'Villes : revenu +10 % ; unités situées dans un bâtiment : défense +5 % ; unités situées en plaine : défense −5 %.',  // FACTIONS.4.trait

  // ── 阵营研究 ──
