  '医护兵': 'Infirmier',  // UNITS.mdc.name
  '摩托兵': 'Motard',  // UNITS.bik.name
  '侦察车': 'Recon',  // UNITS.rec.name
  '轻型坦克': 'Char léger',  // UNITS.tnk.name
  '中型坦克': 'Char moyen',  // UNITS.med.name
  '重型坦克': 'Char lourd',  // UNITS.hvy.name
  '自行火炮': 'Artillerie',  // UNITS.art.name
  '火箭炮': 'Lance-roquettes',  // UNITS.rkt.name
  '防空车': 'DCA',  // UNITS.aa.name
  '防空导弹': 'Lance-missiles',  // UNITS.sam.name
  '维修车': 'Camion-atelier',  // UNITS.rep.name
  '运兵车': 'Transporteur',  // UNITS.apc.name
  '武装直升机': 'Hélico de combat',  // UNITS.cop.name
  '运输直升机': 'Hélico de transport',  // UNITS.tcp.name
  '攻击机': 'Avion d\'attaque',  // UNITS.atk.name
  '轰炸机': 'Bombardier',  // UNITS.bmb.name
  '战斗机': 'Chasseur',  // UNITS.ftr.name
  '炮艇': 'Canonnière',  // UNITS.gbt.name
  '驱逐舰': 'Destroyer',  // UNITS.dst.name
  '潜艇': 'Sous-marin',  // UNITS.sub.name
  '战列舰': 'Cuirassé',  // UNITS.bsh.name
  '登陆艇': 'Barge',  // UNITS.lnd.name

  // ── 兵种说明 ──
  '造价低廉，可占领建筑，可进入山地与河流。': 'Coût très bas. Peut capturer les bâtiments et entrer en montagne et en rivière.',  // UNITS.inf.desc
  '装备火箭筒的步兵，可占领建筑，对坦克伤害较高，在山地、河流上的移动消耗为 1。': 'Fantassin équipé d\'un bazooka : capture les bâtiments, inflige de gros dégâts aux chars et a un coût de déplacement de 1 en montagne et en rivière.',  // UNITS.mech.desc
  '射程 2–4 的远程步兵，擅长攻击步兵类单位，也可攻击轻型车辆和直升机。在山地上射程 +1。移动后不可攻击。': 'Fantassin à distance de portée 2–4, efficace contre les unités d\'infanterie ; peut aussi attaquer les véhicules légers et les hélicoptères. Portée +1 en montagne. Ne peut pas attaquer après un déplacement.',  // UNITS.snp.desc
  '射程 1–2，移动后仍可攻击。攻击时目标的地形防御减半，擅长攻击位于建筑、森林、山地的步兵类单位。攻击 2 格外的目标时不受反击。在山地上射程 +1。不可攻击航空单位和舰船，不可占领。': 'Portée 1–2, peut attaquer après un déplacement. Divise par deux la défense du terrain de la cible ; efficace contre les unités d\'infanterie situées dans un bâtiment, en forêt ou en montagne. Ne subit pas de riposte en attaquant une cible à 2 cases. Portée +1 en montagne. Ne peut ni attaquer les unités aériennes et les navires, ni capturer.',  // UNITS.grn.desc
  '射程 1，攻击时无视目标的地形防御，擅长攻击位于建筑、山地的步兵类单位。迷雾开启时，可发现周围 8 格森林、废墟中的隐蔽单位。不敌远程单位和车辆，不可攻击航空单位和舰船，不可占领。': 'Portée 1. Ignore la défense du terrain de la cible ; efficace contre les unités d\'infanterie situées dans un bâtiment ou en montagne. Avec brouillard, repère les unités camouflées dans les forêts et les ruines des 8 cases alentour. Faible contre les unités à distance et les véhicules. Ne peut ni attaquer les unités aériennes et les navires, ni capturer.',  // UNITS.flm.desc
  '无武装。相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名医护兵的效果不叠加。': 'Non armé. Vos unités d\'infanterie adjacentes récupèrent 2 HP par tour (gratuit). Les effets de plusieurs infirmiers ne se cumulent pas.',  // UNITS.mdc.desc
  '乘坐摩托车的步兵，可占领建筑，移动力高，适合占领远处的建筑。不可进入山地。': 'Fantassin à moto. Peut capturer les bâtiments ; son mouvement élevé convient à la capture des bâtiments éloignés. Ne peut pas entrer en montagne.',  // UNITS.bik.desc
  '陆上单位中移动力最高，擅长攻击步兵类单位和无掩护的火炮，不敌坦克。': 'Mouvement le plus élevé des unités terrestres. Efficace contre les unités d\'infanterie et les canons sans protection, faible contre les chars.',  // UNITS.rec.desc
  '陆上主力，造价较低，攻击与防御均衡。': 'Pilier des forces terrestres : coût réduit, attaque et défense équilibrées.',  // UNITS.tnk.desc
  '攻击与防御高于轻型坦克，造价适中。': 'Attaque et défense supérieures à celles du char léger, coût modéré.',  // UNITS.med.desc
  '陆上单位中攻击与防御最高，造价高，移动力低。': 'Attaque et défense les plus élevées des unités terrestres. Coût élevé, mouvement faible.',  // UNITS.hvy.desc
  '射程 2–3，可攻击舰船。移动后不可攻击，不可攻击相邻的敌方单位。': 'Portée 2–3, peut attaquer les navires. Ne peut pas attaquer après un déplacement ni viser une unité ennemie adjacente.',  // UNITS.art.desc
  '射程 3–5，射程长于自行火炮，擅长攻击重型车辆。移动后不可攻击。': 'Portée 3–5, supérieure à celle de l\'artillerie. Efficace contre les véhicules lourds. Ne peut pas attaquer après un déplacement.',  // UNITS.rkt.desc
  '射程 1，擅长攻击航空单位，对步兵类单位伤害也较高。': 'Portée 1. Efficace contre les unités aériennes ; inflige aussi de gros dégâts aux unités d\'infanterie.',  // UNITS.aa.desc
  '无武装。相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Non armé. Vos véhicules, unités aériennes et navires adjacents récupèrent 1 HP par tour (gratuit).',  // UNITS.rep.desc
  '移动不受地形影响，擅长攻击陆上单位，不敌防空车。': 'Son déplacement ignore le terrain. Efficace contre les unités terrestres, faible contre la DCA.',  // UNITS.cop.desc
  '可攻击陆上单位和直升机，造价低于轰炸机。': 'Peut attaquer les unités terrestres et les hélicoptères. Coûte moins cher que le bombardier.',  // UNITS.atk.desc
  '对陆上单位和舰船伤害极高，不可攻击航空单位。': 'Dégâts très élevés contre les unités terrestres et les navires. Ne peut pas attaquer les unités aériennes.',  // UNITS.bmb.desc
  '造价低廉的小型舰船，可攻击岸边的陆上单位，擅长攻击登陆艇。': 'Petit navire bon marché. Peut attaquer les unités terrestres du rivage ; efficace contre les barges.',  // UNITS.gbt.desc
  '兼具防空与反潜能力，擅长攻击潜艇和航空单位。': 'Antiaérien et anti-sous-marin. Efficace contre les sous-marins et les unités aériennes.',  // UNITS.dst.desc
  '射程 2–6，可攻击陆上单位和舰船，伤害较高。移动后不可攻击。': 'Portée 2–6. Peut attaquer les unités terrestres et les navires, avec des dégâts élevés. Ne peut pas attaquer après un déplacement.',  // UNITS.bsh.desc
