  '停留的己方步兵类单位每回合恢复 4 HP，相邻四格内的己方步兵类单位每回合恢复 2 HP（需支付资金）。': 'Vos unités d\'infanterie qui y stationnent récupèrent 4 HP par tour, celles des quatre cases adjacentes 2 HP par tour (payant).',  // TERRAIN.hospital.note
