  '所惧': 'Craint',  // codex.js:141
  '抛射：移动后仍可攻击。': 'Tir en cloche : peut attaquer après un déplacement.',  // codex.js:169
  '不可攻击相邻的敌方单位，受到相邻敌方单位攻击时也不可反击。': 'Ne peut pas attaquer une unité ennemie adjacente, ni riposter quand une unité ennemie adjacente l\'attaque.',  // codex.js:170
  '攻击时无视目标的地形防御。': 'En attaque, ignore la défense du terrain de la cible.',  // codex.js:171
  '所有阵营均可研究。': 'Accessibles à toutes les factions.',  // codex.js:196
