  '克制表　行为攻击方，列为防守方，数值为基础伤害（%）': 'Table d\'avantages — lignes : attaquant, colonnes : défenseur, valeurs : dégâts de base (%)',  // codex.js:211
  '攻 ＼ 守': 'Att. \\ Déf.',  // codex.js:211
  '胜负': 'Victoire et défaite',  // codex.js:235
  '设有天数上限时，到期后先比较各队的收入建筑数，再比较单位总造价。': 'Avec une limite de jours, à l\'échéance, on compare d\'abord le nombre de bâtiments de revenu de chaque équipe, puis le coût total des unités.',  // codex.js:238
  '每座建筑有 20 点占领值，每次占领减去单位当前的 HP。满 HP 的单位需 2 回合完成占领。': 'Chaque bâtiment a 20 points de capture ; chaque capture en retire les HP actuels de l\'unité. Une unité à HP max achève la capture en 2 tours.',  // codex.js:247
  '占领中的单位离开或被击毁时，占领值恢复为 20。不可占领友方的建筑。': 'Si l\'unité qui capture s\'en va ou est détruite, les points de capture reviennent à 20. Les bâtiments alliés ne peuvent pas être capturés.',  // codex.js:248
  '两个单位的 HP 相加，超过 10 的部分按造价返还资金。': 'Les HP des deux unités s\'additionnent ; la part au-delà de 10 est rendue en fonds, au prorata du coût.',  // codex.js:250
  '受到不相邻的敌方单位攻击时不可反击。': 'Aucune riposte contre une unité ennemie non adjacente.',  // codex.js:260
  '己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Vos unités à 5 cases ou moins d\'une de vos tours radar : attaque +10 %. Les effets de plusieurs tours radar ne se cumulent pas.',  // codex.js:276
  '迷雾开启时，己方雷达塔可看见周围 5 格。': 'Avec brouillard, vos tours radar voient à 5 cases alentour.',  // codex.js:276
  '不提供收入。': 'Ne fournit aucun revenu.',  // codex.js:276
  '可占领建筑的兵种进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP。': 'Une unité capable de capturer les bâtiments peut y lancer un missile, une seule fois : choisissez une case centrale ; toutes les unités à 2 cases ou moins perdent chacune 3 HP.',  // codex.js:277
  '每击毁一个敌方单位，星级 +1，最高 3 星。': 'Chaque unité ennemie détruite donne étoiles +1, 3 étoiles au maximum.',  // codex.js:278
  '每 1 星攻击 +5%、防御 +5%。': 'Pour 1 étoile : attaque +5 %, défense +5 %.',  // codex.js:278
  '运输单位移动后选择“卸载”，将搭载的单位放置到相邻且可进入的空格。卸载的单位本回合不可再行动。': 'Après son déplacement, le transport choisit « Débarquer » et dépose l\'unité embarquée sur une case libre, adjacente et accessible. L\'unité débarquée ne peut plus agir ce tour.',  // codex.js:282
  '技能槽积满后，可在己方回合发动技能，效果持续至己方下回合开始。': 'Une fois la jauge de pouvoir pleine, le pouvoir s\'active pendant votre tour ; son effet dure jusqu\'au début de votre prochain tour.',  // codex.js:284
  '技能仅对己方阵营生效。各指挥官的技能见“指挥官”页。': 'Un pouvoir ne s\'applique qu\'à votre faction. Les pouvoirs de chaque commandant figurent sur la page « Commandants ».',  // codex.js:284
  '特长与阵营特性': 'Spécialité et trait de faction',  // codex.js:285
  '每位指挥官拥有一项特长，开局即生效。': 'Chaque commandant a une spécialité, active dès le début de la partie.',  // codex.js:286
  '指挥官同时具有所属阵营的特性，与本局军队的颜色无关。': 'Un commandant possède aussi le trait de sa faction d\'origine, quelle que soit la couleur de son armée dans la partie.',  // codex.js:287
  '研究点来源：研究经费、己方科研所，以及各阵营的研究方式（见“阵营”页）。': 'Sources de points de recherche : budget de recherche, vos laboratoires et le mode de recherche de chaque faction (voir la page « Factions »).',  // codex.js:294
  '多阵营与结盟': 'Factions multiples et alliances',  // codex.js:308
