  '{fort}上的远程单位、{mountain}上的步兵类远程单位射程 +1，两者不叠加。': 'Unités à distance sur une case {fort} et unités d\'infanterie à distance sur une case {mountain} : portée +1 ; les deux bonus ne se cumulent pas.',
  '{fort}上的远程单位射程 +1，两者不叠加。': 'Unités à distance sur une case {fort} : portée +1 ; les deux bonus ne se cumulent pas.',
  '{mountain}上的步兵类远程单位射程 +1，两者不叠加。': 'Unités d\'infanterie à distance sur une case {mountain} : portée +1 ; les deux bonus ne se cumulent pas.',
  '车辆在{land}修理，航空单位在{airport}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Réparation des véhicules : {land} ; des unités aériennes : {airport} ; des navires : {port}. Les unités d\'infanterie sont réparées dans n\'importe lequel de vos bâtiments.',
  '车辆在{land}修理，航空单位在{airport}修理。步兵类单位可在任意己方建筑修理。': 'Réparation des véhicules : {land} ; des unités aériennes : {airport}. Les unités d\'infanterie sont réparées dans n\'importe lequel de vos bâtiments.',
  '车辆在{land}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Réparation des véhicules : {land} ; des navires : {port}. Les unités d\'infanterie sont réparées dans n\'importe lequel de vos bâtiments.',
  '车辆在{land}修理。步兵类单位可在任意己方建筑修理。': 'Réparation des véhicules : {land}. Les unités d\'infanterie sont réparées dans n\'importe lequel de vos bâtiments.',
  '与{name}相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Vos véhicules, unités aériennes et navires adjacents à cette unité ({name}) récupèrent 1 HP par tour (gratuit).',
  '与{name}相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名{name}的效果不叠加。': 'Vos unités d\'infanterie adjacentes à cette unité ({name}) récupèrent 2 HP par tour (gratuit). Les effets de plusieurs unités de ce type ({name}) ne se cumulent pas.',
