  '击毁敌方的强化单位时，获得它强化价的一半（向上取整）。运输单位搭载的强化单位各自计算。': 'Détruire une unité renforcée ennemie rapporte la moitié de son coût du renfort (arrondie à l\'unité supérieure). Chaque unité renforcée embarquée dans un transport est comptée à part.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': 'Unités d\'infanterie : vision +3 sur une case {mountain}. Vos bâtiments voient leur propre case ; {hq} : 2 cases alentour ; {tower} : 5 cases alentour.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格。': 'Unités d\'infanterie : vision +3 sur une case {mountain}. Vos bâtiments voient leur propre case ; {hq} : 2 cases alentour.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{tower}可看见周围 5 格。': 'Unités d\'infanterie : vision +3 sur une case {mountain}. Vos bâtiments voient leur propre case ; {tower} : 5 cases alentour.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格。': 'Unités d\'infanterie : vision +3 sur une case {mountain}. Vos bâtiments voient leur propre case.',
  '己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': 'Vos bâtiments voient leur propre case ; {hq} : 2 cases alentour ; {tower} : 5 cases alentour.',
