  '完整：每次占领弹出小窗，演出步兵占领建筑的过程；占领司令部时为整屏演出。简短：只在地图上显示跳减的占领值和换色。开启“电脑加速”时，电脑回合自动使用简短演出。': 'Complète : chaque capture ouvre une petite fenêtre qui montre l\'infanterie en train de capturer le bâtiment ; la capture d\'un QG se joue en plein écran. Courte : la carte affiche seulement la baisse des points de capture et le changement de couleur. Avec « IA accélérée », les tours de l\'IA utilisent automatiquement la scène courte.',
