  '隐形的航空单位：敌方只有相邻时才能发现（迷雾关闭时也有效）。对航空单位伤害高，对陆上单位伤害中等。': 'Unité aérienne furtive : l\'ennemi ne la repère que depuis une case adjacente (même sans brouillard). Dégâts élevés contre les unités aériennes, moyens contre les unités terrestres.',
