  '陆上单位结束移动停在这一格时拾取，获得 1–3 份陨星碎片（每个碎片堆在开局时随机决定），这一格变为碎片坑（与荒地相同）。轮式车辆的移动消耗为 3。': 'Une unité terrestre qui termine son déplacement sur cette case le ramasse : 1–3 Éclats de Météore (quantité tirée au hasard pour chaque tas en début de partie) ; la case devient une Fosse d\'Éclats (identique à une friche). Véhicules à roues : coût de déplacement de 3.',
