// 说明文案去口语化（2026-11-13）
AWI18n.add('fr', {
  '黑潮阵营的重装步兵，可占领建筑。对步兵类单位和轻型车辆的伤害高于步兵，受到坦克的伤害明显低于步兵。': 'Infanterie lourde de la Marée d\'Ombre. Peut capturer les bâtiments. Inflige plus de dégâts que le fantassin aux unités d\'infanterie et aux véhicules légers, et subit nettement moins de dégâts des chars.',
  '黑潮阵营的重型坦克，攻击和防御都高于重型坦克。攻击后可再移动 1 格（不可再次攻击）。': 'Char lourd de la Marée d\'Ombre, supérieur au char lourd en attaque comme en défense. Après avoir attaqué, peut encore se déplacer de 1 case (sans attaquer de nouveau).',
  '每回合提供 100 资金。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。被敌方占领时，己方败北。': 'Fournit 100 fonds par tour. Vos unités terrestres qui y stationnent récupèrent 2 HP par tour (payant). Sa capture par l\'ennemi entraîne votre défaite.',
  '大闸的机房。停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。在会涨水的关卡中，每占有一座闸房，下一次涨水推迟 1 天；全部占有时停止涨水。': 'Salle des machines de la Grande Vanne. Vos unités d\'infanterie qui y stationnent récupèrent 2 HP par tour (payant). Dans les missions où l\'eau monte, chaque poste de vanne que vous possédez retarde de 1 jour la prochaine montée des eaux ; si vous les possédez tous, l\'eau cesse de monter.',
  '车辆的移动力更高，步兵类单位的攻击略低。技能“闪击”：本回合全军的移动力和攻击提高。': 'Les véhicules ont un mouvement plus élevé ; les unités d\'infanterie ont une attaque légèrement plus faible. Pouvoir « Guerre éclair » : ce tour, le mouvement et l\'attaque de toutes vos unités augmentent.',
  '各型坦克的攻击和防御更高，其他单位的攻击较低。技能“履带洪流”：各型坦克攻击后可以再移动。': 'Les chars légers, moyens et lourds ont une attaque et une défense plus élevées ; les autres unités ont une attaque plus faible. Pouvoir « Déferlante blindée » : les chars légers, moyens et lourds peuvent se déplacer à nouveau après une attaque.',
  '远程单位的攻击更高，其中自行火炮和火箭炮提高最多。技能“炮火覆盖”：所有敌方单位损失 HP。': 'Les unités à distance ont une attaque plus élevée ; la hausse est la plus forte pour l\'artillerie et les lance-roquettes. Pouvoir « Pilonnage » : toutes les unités ennemies perdent des HP.',
  '新生产的单位当回合可以行动，所有单位造价 +10%。技能“加班”：本回合造价降低，每座生产建筑可以生产 2 次。': 'Les unités nouvellement produites peuvent agir le tour même ; coût de toutes les unités +10 %. Pouvoir « Heures sup » : ce tour, le coût des unités baisse et chaque bâtiment de production peut produire 2 fois.',
  '赤焰喷火兵部队的指挥官，炉前工出身，脸上有疤。嫌远距离打仗像写信吵架，喜欢凑到跟前。': 'Commandante du corps des lance-flammes de la Flamme Écarlate, ancienne ouvrière de fourneau, le visage balafré. Se battre de loin, pour elle, c\'est se disputer par lettres : elle préfère venir tout près.',
  '喷火兵和破甲兵的攻击、移动力更高，造价更低。技能“燎原”：喷火兵的攻击波及周围的敌方单位，并把森林变为荒地。': 'Les lance-flammes et les bazookas ont une attaque et un mouvement plus élevés et coûtent moins cher. Pouvoir « Embrasement » : l\'attaque des lance-flammes touche aussi les unités ennemies alentour et change la forêt en friche.',
  '己方单位被相邻的敌方单位攻击时先手反击。技能“架盾”：反击伤害 ×2，全军防御提高。': 'Vos unités attaquées par une unité ennemie adjacente ont la riposte anticipée. Pouvoir « Boucliers levés » : dégâts de riposte ×2 ; la défense de toutes vos unités augmente.',
  '舰船的攻击、防御和移动力更高，造价更低。技能“怒潮”：全军恢复 HP，舰船对陆上单位的伤害提高。': 'Les navires ont une attaque, une défense et un mouvement plus élevés et coûtent moins cher. Pouvoir « Marée furieuse » : toutes vos unités récupèrent des HP ; les navires infligent plus de dégâts aux unités terrestres.',
  '攻击机、轰炸机、战斗机的攻击更高，造价更低。技能“俯冲”：航空单位攻击时不受反击。': 'Les avions d\'attaque, les bombardiers et les chasseurs ont une attaque plus élevée et coûtent moins cher. Pouvoir « Piqué » : les unités aériennes ne subissent pas de riposte en attaquant.',
  '武装直升机的攻击和防御更高，运输直升机的搭载数更多。技能“蜂群”：直升机攻击后可以再移动。': 'Les hélicos de combat ont une attaque et une défense plus élevées ; les hélicos de transport ont une capacité plus élevée. Pouvoir « Essaim » : les hélicoptères peuvent se déplacer à nouveau après une attaque.',
  '潜艇的攻击更高，只有相邻时才会被发现。技能“狼群”：潜艇攻击大幅提高，攻击时不受反击。': 'Les sous-marins ont une attaque plus élevée et ne sont repérés que par une unité adjacente. Pouvoir « Meute » : l\'attaque des sous-marins augmente fortement ; ils ne subissent pas de riposte en attaquant.',
  '防空车、防空导弹和战斗机对航空单位的伤害更高，造价更低。技能“天网”：敌方航空单位进入射程时自动受到攻击。': 'Les DCA, les lance-missiles et les chasseurs infligent plus de dégâts aux unités aériennes et coûtent moins cher. Pouvoir « Filet céleste » : les unités aériennes ennemies qui entrent à portée de ces unités subissent automatiquement une attaque.',
  '苍蓝舰队医院的医生。送到他手上的人，不管哪一方的，都要活着下手术台。爱管别人吃没吃饭。': 'Médecin de l\'hôpital de la flotte de l\'Azur Profond. Quiconque arrive entre ses mains, de n\'importe quel camp, quitte la table d\'opération vivant. Vérifie toujours si les autres ont mangé.',
  '己方单位每回合恢复 1 HP，在建筑上修理免费。技能“急救”：全军恢复 HP，并复活最近被击毁的一个单位。': 'Vos unités récupèrent 1 HP par tour et sont réparées gratuitement dans les bâtiments. Pouvoir « Premiers secours » : toutes vos unités récupèrent des HP et votre dernière unité détruite ressuscite.',
  '步兵类单位的攻击、占领值和视野更高。技能“全民皆兵”：己方城市出现步兵。': 'Les unités d\'infanterie ont une attaque, des points de capture et une vision plus élevés. Pouvoir « Levée en masse » : des fantassins apparaissent dans vos villes.',
  '狙击手的射程和攻击更高，移动后可以攻击。技能“一击”：狙击手、投弹手的运气取最大值，并无视目标的地形防御。': 'Les snipers ont une portée et une attaque plus élevées et peuvent attaquer après un déplacement. Pouvoir « Tir décisif » : les snipers et les grenadiers ont la chance maximale et ignorent la défense du terrain de la cible.',
  '翠林负责山路和暗号的人，没人说得清她是哪个寨子的。擅长让对手先看见一点东西，再发现看错了。': 'Responsable des sentiers et des codes de la Forêt de Jade ; personne ne sait de quel village elle vient. Son art : laisser l\'adversaire voir un peu, puis découvrir qu\'il a mal vu.',
  '位于森林、废墟、礁石的己方单位攻击和防御更高，只有相邻时才会被发现。技能“灯火管制”：敌方单位的视野降为 1。': 'Vos unités situées en forêt, dans des ruines ou sur un récif ont une attaque et une défense plus élevées et ne sont repérées que par une unité adjacente. Pouvoir « Black-out » : la vision des unités ennemies est réduite à 1.',
  '直射单位攻击后，可以用剩余的移动力再移动。技能“风驰”：全军移动力提高，攻击时不受反击。': 'Après une attaque, les unités de tir direct peuvent se déplacer à nouveau avec leur mouvement restant. Pouvoir « À toute allure » : le mouvement de toutes vos unités augmente ; elles ne subissent pas de riposte en attaquant.',
  '己方单位在能进入的地形上，移动消耗都是 1。技能“寒潮”：敌方单位的移动力和视野降低。': 'Vos unités ont un coût de déplacement de 1 sur tous les terrains accessibles. Pouvoir « Vague de froid » : le mouvement et la vision des unités ennemies diminuent.',
  '己方单位的攻击不随 HP 减少而降低。技能“背水”：HP 未满的单位攻击大幅提高。': 'L\'attaque de vos unités ne baisse pas avec la perte de HP. Pouvoir « Dos au mur » : l\'attaque des unités aux HP incomplets augmente fortement.',
  '金沙七邦的司库，主管财务。只认账本，不划算的仗不打。脾气很好，从不发火，因为发火不挣钱。': 'Trésorier des Sept États des Sables d\'Or, chargé des finances. Ne croit que ses livres de comptes ; une guerre qui ne rapporte pas, il ne la fait pas. Toujours aimable, jamais en colère : la colère ne rapporte rien.',
  '所有单位造价 −10%，全军攻击 −10%。技能“军费”：立即获得一笔资金。': 'Toutes les unités : coût −10 % ; toutes vos unités : attaque −10 %. Pouvoir « Trésor de guerre » : vous recevez aussitôt des fonds.',
  '金沙的佣兵首领，赌场少东家。谁出价高替谁打，只押赢的那边。': 'Chef des mercenaires des Sables d\'Or, fils d\'un patron de casino. Se bat pour le plus offrant, ne mise que sur le gagnant.',
  '攻击的运气范围很大，伤害的起伏也大。技能“梭哈”：运气判定三次，取最高值。': 'La plage de chance des attaques est très large, et les dégâts varient fortement. Pouvoir « Tapis » : la chance est tirée trois fois et la meilleure valeur est retenue.',
  '占领值更高，每占领一座建筑都获得资金。技能“加征”：立即获得相当于一个回合的收入。': 'Les points de capture sont plus élevés, et chaque bâtiment capturé rapporte des fonds. Pouvoir « Surtaxe » : vous recevez aussitôt l\'équivalent du revenu d\'un tour.',
  '己方城市也可以生产步兵类单位，步兵类单位造价更低。技能“黑市”：可以出售己方单位，返还造价的 90%。': 'Vos villes peuvent aussi produire les unités d\'infanterie, et les unités d\'infanterie coûtent moins cher. Pouvoir « Marché noir » : vous pouvez vendre vos unités ; la vente rend 90 % de leur coût.',
  '侦察车、摩托兵的移动力和攻击更高，攻击后可以再移动。技能“穿插”：侦察车、摩托兵、运兵车可以穿过敌方单位。': 'Les recons et les motards ont un mouvement et une attaque plus élevés et peuvent se déplacer à nouveau après une attaque. Pouvoir « Infiltration » : les recons, motards et transporteurs peuvent traverser les unités ennemies.',
  '位于建筑或 2 星及以上地形的单位防御更高。技能“铁壁”：全军恢复 HP，防御提高。': 'Les unités situées dans un bâtiment ou sur un terrain à 2 étoiles ou plus ont une défense plus élevée. Pouvoir « Mur de fer » : toutes vos unités récupèrent des HP et leur défense augmente.',
  '黑潮阵营的首领，六十六岁，见过三次退潮。六岁那次没了家，三十六岁那次没了妻儿。劝和、划界、分矿他都试过，每次只管三十年。说话慢，从不提高声音，说过的话一定算数。': 'Chef de la Marée d\'Ombre, soixante-six ans, trois reflux vécus. Au premier, à six ans, il perd son foyer ; au deuxième, à trente-six ans, sa femme et son fils. Médiations, frontières, partage du minerai : il a tout essayé, et rien n\'a tenu plus de trente ans. Parle lentement, n\'élève jamais la voix, tient toujours parole.',
  '位于荒地、废墟、陨星矿的己方单位防御更高。技能“开闸”：涨水一级，与海洋相邻的沙滩、荒地、礁石、废墟变为海洋。': 'Vos unités situées sur une friche, des ruines ou une mine de Météore ont une défense plus élevée. Pouvoir « Vannes ouvertes » : l\'eau monte d\'un niveau ; les plages, friches, récifs et ruines adjacents à la mer deviennent mer.',
  '主管海军': 'Chef de la Marine',
  '黑潮阵营的大将，主管海军。五十八岁，老船长，四国通用的潮汐表是他年轻时编的。上一次战争，他的船队被四国轮流征用，沉得一条不剩。从那以后他只信海。像个教书先生，动手之前先讲道理。': 'Général de la Marée d\'Ombre, chef de la Marine. Cinquante-huit ans, vieux capitaine : les tables des marées en usage dans les quatre nations, c\'est lui qui les a établies dans sa jeunesse. À la dernière guerre, sa flotte a été réquisitionnée tour à tour par les quatre nations ; pas un navire n\'est resté à flot. Depuis, il ne croit qu\'à la mer. Des airs de maître d\'école : il explique avant de frapper.',
  '舰船的攻击和移动力更高；迷雾开启时，视野范围内礁石里的敌方单位也可见。技能“大潮”：敌方舰船的移动力大幅降低。': 'Les navires ont une attaque et un mouvement plus élevés ; avec brouillard, les unités ennemies sur récif situées dans votre champ de vision sont aussi visibles. Pouvoir « Grande marée » : le mouvement des navires ennemis diminue fortement.',
  '主管财务': 'Cheffe des Finances',
  '黑潮阵营的大将，主管财务，负责收买对手。四十一岁。她家三代的商行在上一次战争里赔得精光。她算过：打仗是世上最亏的买卖，每三十年亏一次，不如一次清账。客气，从不发火，说话只说一遍。': 'Générale de la Marée d\'Ombre, cheffe des Finances, chargée d\'acheter les adversaires. Quarante et un ans. La maison de commerce de sa famille, vieille de trois générations, a tout perdu à la dernière guerre. Son calcul : la guerre est la pire des affaires, à perte tous les trente ans ; autant solder le compte une fois pour toutes. Courtoise, jamais en colère, ne dit les choses qu\'une fois.',
  '所有单位造价更低，击毁敌方单位可以获得资金。技能“收购”：支付资金，买下与己方单位相邻的敌方车辆，最多 2 个。': 'Toutes les unités coûtent moins cher, et détruire une unité ennemie rapporte des fonds. Pouvoir « Rachat » : vous payez des fonds pour acheter les véhicules ennemis adjacents à vos unités, 2 au plus.',
  '主管交通': 'Chef des Transports',
  '黑潮阵营的大将，主管交通，黑色装甲列车“黑潮号”的车长。三十五岁，修了半辈子路。他修的每一条路都被拿去运兵，路铺到哪，仗打到哪。他想铺完最后一条，从此世上不用再铺路。话少，力气大，认死理。': 'Général de la Marée d\'Ombre, chef des Transports et chef du train blindé noir, le Marée d\'Ombre. Trente-cinq ans, dont la moitié à construire des routes. Toutes ont servi à transporter des troupes : où va la voie, va la guerre. Il veut poser la dernière, pour que le monde n\'en ait plus jamais besoin. Peu de mots, beaucoup de force, une seule idée en tête.',
  '车辆在道路和桥梁上的防御更高；回合开始时位于道路、桥梁的车辆移动力更高。技能“封路”：敌方单位在道路和桥梁上的移动消耗增加。': 'Les véhicules ont une défense plus élevée sur les routes et les ponts ; les véhicules qui commencent le tour sur une route ou un pont ont un mouvement plus élevé. Pouvoir « Route barrée » : le coût de déplacement des unités ennemies augmente sur les routes et les ponts.',
  '主管情报': 'Cheffe du Renseignement',
  '黑潮阵营的大将，主管情报：潜伏，冒充，挑拨。二十四岁。她是在战争烧剩的寨子里被玄渊捡回来的孩子，管他叫爷爷。爱笑，说话像开玩笑，下手不开玩笑。': 'Générale de la Marée d\'Ombre, cheffe du Renseignement : infiltrer, usurper, diviser. Vingt-quatre ans. Xuan Abîme l\'a recueillie enfant dans un village brûlé par la guerre ; elle l\'appelle grand-père. Rieuse, parle comme on plaisante, ne plaisante pas quand elle frappe.',
  '位于建筑的己方步兵类单位处于隐蔽状态。技能“点灯”：让分属两个敌方阵营的相邻单位互相攻击。': 'Vos unités d\'infanterie dans un bâtiment sont camouflées. Pouvoir « Lampe allumée » : des unités adjacentes appartenant à deux factions ennemies différentes s\'attaquent l\'une l\'autre.',
  '本回合：狙击手、投弹手攻击时，运气取最大值，并无视目标的地形防御。全军攻击 +30%。': 'Ce tour, les attaques des snipers et des grenadiers ont la chance maximale et ignorent la défense du terrain de la cible. Toutes vos unités : attaque +30 %.',
  '本回合：己方攻击的运气判定三次，取最高值。全军攻击 +30%。第一次击毁敌方单位时，返还 50% 技能槽。': 'Ce tour, la chance de vos attaques est tirée trois fois et la meilleure valeur est retenue. Toutes vos unités : attaque +30 %. La première destruction d\'une unité ennemie rend 50 % de la jauge de pouvoir.',
  '本回合：单位造价 −30%，每座生产建筑可生产 2 次。生产第二个单位前，要先把第一个单位移出建筑。': 'Ce tour, coût des unités −30 % ; chaque bâtiment de production peut produire 2 fois. Avant de produire la deuxième unité, vous devez déplacer la première hors du bâtiment.',
  '己方下回合开始前：敌方航空单位移动后进入己方防空车、防空导弹、战斗机的射程时，自动受到一次攻击（每个己方单位一次）。全军防御 +30%。': 'Jusqu\'au début de votre prochain tour, une unité aérienne ennemie qui entre à portée de vos DCA, lance-missiles ou chasseurs après un déplacement subit automatiquement une attaque (une seule par unité à vous). Toutes vos unités : défense +30 %.',
  '立即获得相当于一个回合的收入。本回合：步兵类单位移动力 +1。': 'Vous recevez aussitôt l\'équivalent du revenu d\'un tour. Ce tour, unités d\'infanterie : mouvement +1.',
  '打开大闸，涨水一级。与海洋相邻的沙滩、荒地、礁石、废墟变为海洋。位于这些格子的陆上单位被移到最近的空格，其中敌方单位损失 3 HP（不会被击毁）。己方下回合开始前：全军防御 +20%。每局最多涨水 2 次。不能涨水时，改为所有敌方单位各损失 1 HP（不会被击毁）。': 'Ouvre la Grande Vanne et fait monter l\'eau d\'un niveau. Les plages, friches, récifs et ruines adjacents à la mer deviennent mer. Les unités terrestres situées sur ces cases sont déplacées vers la case libre la plus proche ; parmi elles, les unités ennemies perdent 3 HP (sans être détruites). Jusqu\'au début de votre prochain tour, toutes vos unités : défense +20 %. L\'eau peut monter 2 fois au plus par partie. Si l\'eau ne peut pas monter, toutes les unités ennemies perdent 1 HP chacune à la place (sans être détruites).',
  '买下与己方单位相邻的敌方车辆，最多 2 个，从价格高的开始买。买下的单位立即归己方所有，当回合不能行动。价格 = 造价 × 剩余 HP ÷ 10 × 50%。资金不够支付的单位不会买下。以下单位不能买：带标记的单位、搭载着单位的运输单位、位于司令部的单位、敌方阵营的最后一个单位。一个单位都没有买下时，改为获得回合收入的 50%。': 'Achète les véhicules ennemis adjacents à vos unités, 2 au plus, en commençant par les plus chers. Une unité achetée passe aussitôt dans votre camp et ne peut pas agir ce tour. Prix = coût × HP restants ÷ 10 × 50 %. Une unité que vos fonds ne suffisent pas à payer n\'est pas achetée. Ne peuvent pas être achetées : les unités marquées, les unités de transport qui embarquent des unités, les unités situées dans un QG et la dernière unité d\'une faction ennemie. Si aucune unité n\'est achetée, vous recevez à la place 50 % de votre revenu par tour.',
  '相邻且分属不同敌方阵营的两个单位互相攻击一次，最多 2 对，每个单位只算进一对。这次攻击不会击毁单位，也不积累技能槽。没有符合条件的单位时，改为以下效果。本回合：己方攻击 +20%，攻击时不受反击。己方下回合开始前：敌方视野 −2。': 'Deux unités adjacentes appartenant à des factions ennemies différentes s\'attaquent l\'une l\'autre une fois, 2 paires au plus ; chaque unité ne compte que dans une seule paire. Ces attaques ne détruisent aucune unité et ne remplissent pas la jauge de pouvoir. Si aucune unité ne remplit ces conditions, l\'effet suivant s\'applique à la place. Ce tour, vos unités : attaque +20 %, aucune riposte subie en attaquant. Jusqu\'au début de votre prochain tour, vision ennemie −2.',
  '远程：移动后不可攻击，只有不移动时才可以攻击。': 'À distance : pas d\'attaque après un déplacement ; l\'unité ne peut attaquer que si elle ne se déplace pas.',
  '一个阵营的司令部被占领，或者全部单位被击毁时，这个阵营败北。只剩一支队伍时，这支队伍获胜。': 'Une faction est vaincue quand son QG est capturé ou que toutes ses unités sont détruites. Quand il ne reste qu\'une équipe, elle l\'emporte.',
  '受到相邻敌方单位攻击的单位如果没有被击毁，会反击，伤害按受到攻击后的 HP 计算。': 'Une unité attaquée par une unité ennemie adjacente riposte si elle n\'est pas détruite ; les dégâts sont calculés avec ses HP après l\'attaque.',
  '远程单位移动后不可攻击，只有不移动时才可以攻击。{list}例外，移动后仍可攻击。': 'Une unité à distance ne peut pas attaquer après un déplacement : elle ne peut attaquer que si elle ne se déplace pas. Exception : {list} (attaque possible après un déplacement).',
  '远程单位移动后不可攻击，只有不移动时才可以攻击。': 'Les unités à distance n\'attaquent pas après un déplacement : elles ne peuvent attaquer que si elles ne se déplacent pas.',
  '没有添加内容': 'Aucun contenu ajouté',
  '上一局使用了这些扩展，现在没有启用，所以不能继续：{list}。存档仍然保留，重新启用这些扩展后可以继续。': 'La dernière partie utilisait ces mods, qui ne sont pas activés ; elle ne peut donc pas reprendre : {list}. La sauvegarde est conservée : réactivez ces mods pour continuer.',
  'id「{a}」和文件夹名「{b}」不一致': 'L\'id « {a} » ne correspond pas au nom du dossier « {b} »',
  '同一个 id 重复登记': 'Le même id est enregistré plusieurs fois',
  '{a} 必须是数组': '{a} doit être un tableau',
  '{a} 必须是对象': '{a} doit être un objet',
  '地图「{a}」的 rows / half 必须是等宽的字符串数组': 'Carte « {a} » : rows / half doit être un tableau de chaînes de même longueur',
  '指挥官「{a}」的 faction 必须是 1–5': 'Commandant « {a} » : faction doit valoir 1–5',
  '指挥官「{a}」的 mods 必须是数组': 'Commandant « {a} » : mods doit être un tableau',
  '指挥官「{a}」的 mods 里有无法识别的字段 {b}': 'Commandant « {a} » : champ inconnu dans mods : {b}',
  '指挥官「{a}」的 mods 里有无法识别的兵种类别 {b}': 'Commandant « {a} » : catégorie d\'unité inconnue dans mods : {b}',
  '指挥官「{a}」的 {b} 必须是对象': 'Commandant « {a} » : {b} doit être un objet',
  '指挥官「{a}」的 fx.{b} 里有无法识别的兵种类别 {c}': 'Commandant « {a} » : catégorie d\'unité inconnue dans fx.{b} : {c}',
  'balance 里有无法识别的字段 {a}': 'Champ inconnu dans balance : {a}',
  'mod.js 没有调用 AWMods.register（脚本出错，或者 id 不一致）': 'mod.js n\'a pas appelé AWMods.register (erreur dans le script, ou id qui ne correspond pas)',
  '扩展 id 里有不能使用的字符': 'L\'id du mod contient des caractères interdits',
  '指挥官「{a}」的 rules 里有无法识别的效果 {b}': 'Commandant « {a} » : effet inconnu dans rules : {b}',
  '指挥官「{a}」的 fx 里有无法识别的效果 {b}': 'Commandant « {a} » : effet inconnu dans fx : {b}',
  '获得 S 评价的指挥官': 'Commandants avec un rang S',
  '只有一名玩家对战电脑的对局才评分。': 'Seules les parties d\'un joueur contre l\'IA sont notées.',
  '开局资金、建筑收入、人数补偿使用这张地图的默认设置时才评分。': 'Pour être notée, la partie doit garder les fonds de départ, le revenu des bâtiments et la compensation d\'effectif par défaut de cette carte.',
  '队伍使用这张地图的默认分法时才评分。': 'Pour être notée, la partie doit garder les équipes par défaut de cette carte.',
  '这位指挥官首次获得 S 评价': 'Premier rang S avec ce commandant',
  '在困难难度获得 S 评价': 'Rang S en Difficile',
  '距离 S 评价还差 {n} 分': 'À {n} points du rang S',
  '完成过对局的地图': 'Cartes avec une partie terminée',
  '黑潮阵营的大将，主管海军。四国通用的潮汐表是他年轻时编的。': 'Général de la Marée d\'Ombre, chef de la Marine. Les tables des marées des quatre nations sont son œuvre de jeunesse.',
  '黑潮阵营的大将，主管情报。她是在烧剩的寨子里被玄渊捡回来的孩子，管他叫爷爷。': 'Générale de la Marée d\'Ombre, cheffe du Renseignement. Xuan Abîme l\'a recueillie enfant dans un village brûlé ; elle l\'appelle grand-père.',
  '黑潮阵营的大将，主管财务，负责收买对手。她家三代的商行在上一次战争里赔光了。': 'Générale de la Marée d\'Ombre, cheffe des Finances, chargée d\'acheter les adversaires. La maison de commerce familiale, trois générations, a tout perdu à la dernière guerre.',
  '位于森林、废墟、礁石的己方单位攻击 +20%、防御 +20%，迷雾关闭时也处于隐蔽状态。位于平原、道路、桥梁、沙滩的己方单位防御 −5%。迷雾开启时全军视野 +2。己方单位移动中遇到隐蔽的敌方单位时停止移动，但行动不结束。': 'Vos unités situées en forêt, dans des ruines ou sur un récif : attaque +20 %, défense +20 %, camouflées même sans brouillard. Vos unités situées en plaine, sur une route, un pont ou une plage : défense −5 %. Avec brouillard, toutes vos unités : vision +2. Une de vos unités qui rencontre une unité ennemie camouflée pendant son déplacement s\'arrête, mais son action continue.',
  '己方攻击的运气范围变为 0 至 +40（原来 0–9）。运气超过 9 的部分按比例计入伤害：计入量 = 超出部分 × 基础伤害 ÷ 100（基础伤害超过 100 时按 100 计算）。': 'La plage de chance de vos attaques devient 0 à +40 (0–9 à l\'origine). La part de chance au-delà de 9 est ajoutée aux dégâts en proportion : montant ajouté = excédent × dégâts de base ÷ 100 (les dégâts de base supérieurs à 100 comptent pour 100).',
  '占领值 ×1.5。每占领一座建筑，获得 150 资金；占领的是敌方建筑时，再获得 150 资金。全军攻击 −10%。': 'Points de capture ×1.5. Chaque bâtiment capturé rapporte 150 fonds ; s\'il était ennemi, il rapporte 150 fonds de plus. Toutes vos unités : attaque −10 %.',
  '位于建筑的己方步兵类单位处于隐蔽状态，迷雾关闭时也有效。步兵类单位攻击 +15%、占领值 ×1.5。迷雾开启时全军视野 +1。': 'Vos unités d\'infanterie dans un bâtiment sont camouflées, même sans brouillard. Unités d\'infanterie : attaque +15 %, points de capture ×1.5. Avec brouillard, toutes vos unités : vision +1.',
  '各型坦克防御 +15%。': 'Chars légers, moyens et lourds : défense +15 %.',
  '远程单位攻击时，目标的地形防御 −1 星。': 'Quand une unité à distance attaque : défense du terrain de la cible −1 étoile.',
  '远程单位攻击后，目标相邻四格内的敌方单位各受到本次伤害的 20%（不会被击毁；每个单位每回合因溅射最多损失 5 HP）。': 'Après l\'attaque d\'une unité à distance, les unités ennemies des quatre cases adjacentes à la cible subissent chacune 20 % des dégâts infligés (sans être détruites ; chaque unité perd au plus 5 HP par tour par dégâts de zone).',
  '每经过 4 个己方回合，没有单位的己方城市各免费出现一个步兵，每次最多 4 个，当回合可行动。': 'Tous les 4 tours à vous, un fantassin apparaît gratuitement dans chacune de vos villes inoccupées, 4 au plus à chaque fois ; il peut agir le tour même.',
  '每座兵工厂每回合额外提供 1 研究点，最多 4 研究点；研究经费选“停”档时仍然有效。': 'Chaque usine fournit 1 point de recherche de plus par tour, 4 points de recherche au maximum ; cela vaut aussi quand le budget de recherche est sur « Arrêt ».',
  '每回合额外获得 5 研究点（研究经费选“停”档时没有）。各档研究经费 +20%。': '5 points de recherche supplémentaires par tour (sans effet si le budget de recherche est sur « Arrêt »). Budget de recherche de chaque palier : +20 %.',
  '每个敌方回合，第一个移动后进入己方防空导弹射程的敌方航空单位自动受到一次攻击。': 'À chaque tour ennemi, la première unité aérienne ennemie qui entre à portée de vos lance-missiles après un déplacement subit automatiquement une attaque.',
  '位于山地、沼泽的己方单位也处于隐蔽状态，规则与森林、废墟、礁石相同。': 'Vos unités situées en montagne ou dans un marais sont elles aussi camouflées, selon les mêmes règles qu\'en forêt, dans les ruines et sur les récifs.',
  '每回合第一次主动攻击时，运气判定两次，取较高值。': 'À votre première attaque à l\'initiative du tour, la chance est tirée deux fois ; la meilleure valeur est retenue.',
});
